-- 022_tennis_top100_and_2026_history.sql
-- Top 100 ATP snapshot (Oct 5, 2026) + 2026 Grand Slam v1.2 back-test.

update public.assets set active=false where sport='Tennis';

on conflict (sport,external_key) do update
set name=excluded.name,asset_type='TENNIS_PLAYER',active=true,metadata=excluded.metadata;

values(
  'Tennis','2026-27','ACTIVE',
  'https://www.tennislive.net/atp/ranking/',
  '2026-10-05','2027-09-12'
)
on conflict (sport,label) do update
set status='ACTIVE',source_ref=excluded.source_ref,starts_on=excluded.starts_on,ends_on=excluded.ends_on;

select e.id,a.id,true,'CONFIRMED',e.source_ref
from public.competition_editions e
join public.assets a on a.sport='Tennis' and a.active=true
where e.sport='Tennis' and e.label='2026-27'
on conflict (edition_id,asset_id) do update
set draftable=true,entry_status='CONFIRMED',source_ref=excluded.source_ref;

on conflict (asset_id,season_label,scoring_version) do update
set points=excluded.points,source_ref=excluded.source_ref,breakdown=excluded.breakdown,updated_at=now();

with ranked as (
  select ass.id as stat_id,rank() over(order by ass.points desc)::int as calculated_rank
  from public.asset_season_stats ass
  join public.assets a on a.id=ass.asset_id
  where a.sport='Tennis' and a.active=true
    and ass.season_label='2026' and ass.scoring_version='v1.2'
)
update public.asset_season_stats ass
set rank=ranked.calculated_rank,updated_at=now()
from ranked where ranked.stat_id=ass.id;
